-- Enable post-combat regrouping for the audited 63 waypoint patrols (including Valorcall).
-- Requires core support for FLAG_REGROUP_BEFORE_PATROL (0x8000).
-- Preserve the original follow and mutual aggro flags (0x0203).

UPDATE `creature_linking_template`
SET `flag` = `flag` | 32768
WHERE `flag` = 515
  AND (`entry`, `map`, `master_entry`, `search_range`) IN (
  (2764, 0, 2611, 0),
  (2765, 0, 2611, 0),
  (4063, 0, 2611, 0),
  (2738, 0, 2612, 0),
  (2721, 0, 2714, 0),
  (390, 0, 330, 0)
  );

